targets.query:
start = time(v: ${__from}000000)
stop  = time(v: ${__to}000000)
from(bucket:"telemetry") |> range(start: start, stop: stop) |> filter(fn:(r) => r._measurement == "telemetry" and r._field == "pv_power_w") |> drop(columns: ["grid_status", "inverter_mode", "device_id"]) |> set(key: "_field", value: "Сонячні панелі") |> aggregateWindow(every: 5m, fn: mean)

